async function resolvePathwayByName(client, name) {
  const pathways = await cachedFetch(
    () => client.get("/v1/pathways"),
    "pathways",
    "/v1/pathways"
  );
  const lower = name.toLowerCase();
  const matches = pathways.filter((p) => p.name.toLowerCase() === lower);
  if (matches.length === 0) {
    const available = pathways.map((p) => `  ${p.id}: ${p.name}`).join("\n");
    throw new Error(`Pathway "${name}" not found. Available:
${available}`);
  }
  if (matches.length > 1) {
    const ambiguous = matches.map((p) => `  ${p.id}: ${p.name}`).join("\n");
    throw new Error(`Ambiguous pathway name "${name}". Matches:
${ambiguous}`);
  }
  return matches[0];
}

