var recordTasksPath = (recordId) => `/v1/records/${encodeURIComponent(recordId)}/tasks`;
var recordTaskActionPath = (recordId, taskId, action) => `${recordTasksPath(recordId)}/${taskId}/${action}`;
function assignTaskRequest(opts) {
  const legacy = opts.data ? JSON.parse(opts.data) : {};
  const taskId = Number(opts.taskId ?? legacy.task_id);
  const userId = Number(opts.userId ?? legacy.user_id);
  if (!Number.isInteger(taskId) || taskId <= 0) {
    throw new Error("Missing or invalid --task-id <id>.");
  }
  if (!Number.isInteger(userId) || userId <= 0) {
    throw new Error("Missing or invalid --user-id <id>.");
  }
  return {
    path: recordTaskActionPath(opts.recordId, taskId, "assign-user"),
    body: { user_id: userId }
  };
}

