// .path-cli/src/commands/archive-record.ts
var archiveRecordCommand = new Command("archive-record").description(
  "Archive a record (or several with --record-ids) via the Archive Record step"
).option("--record-id <id>", "Record ID").option("--record-ids <ids>", "Comma-separated record IDs").option(
  "--bo-id <id>",
  "Business object ID (skips the lookup; only with a single --record-id)"
).action(async (opts) => {
  try {
    const parentOpts = archiveRecordCommand.parent?.opts() ?? {};
    const config2 = loadConfig({
      accountId: parentOpts.account,
      baseUrl: parentOpts.baseUrl
    });
    if (!config2.accountId) {
      throw new Error(
        'Missing --account <id>. Run "path list-accounts" to see available accounts.'
      );
    }
    const ids = [
      ...opts.recordId ? [String(opts.recordId)] : [],
      ...opts.recordIds ? String(opts.recordIds).split(",").map((s) => s.trim()).filter(Boolean) : []
    ];
    if (ids.length === 0) {
      throw new Error("Pass --record-id <id> or --record-ids <id,id,...>.");
    }
    if (opts.boId && ids.length > 1) {
      throw new Error("--bo-id only applies to a single --record-id.");
    }
    const client = new HttpClient(config2);
    const results = [];
    for (const id of ids) {
      try {
        let boId3 = opts.boId ? parseInt(opts.boId, 10) : NaN;
        if (Number.isNaN(boId3) || isRealWorld()) {
          const record2 = await client.get(
            `/v1/records/${id}`
          );
          if (record2.archived_on) {
            results.push({ record_id: id, status: "already_archived" });
            continue;
          }
          boId3 = record2.business_object_id;
        }
        await assertArchiveRecord(client, boId3, `archive record ${id}`);
        await client.post(
          "/v1/pathways/-1/execute",
          {
            step_type: "archive",
            input_content: { id, business_object_id: boId3 }
          },
          recordContextHeaders(id)
        );
        results.push({ record_id: id, status: "archived" });
      } catch (err) {
        results.push({
          record_id: id,
          status: "failed",
          message: err instanceof Error ? err.message : String(err)
        });
      }
    }
    const format = parentOpts.json ? "json" : void 0;
    const fields = parentOpts.fields?.split(",").map((s) => s.trim());
    console.log(
      formatOutput(ids.length === 1 ? results[0] : results, {
        format,
        fields,
        quiet: parentOpts.quiet
      })
    );
    if (results.some((r) => r.status === "failed")) {
      setExitCode(1);
    }
  } catch (err) {
    handleError(err);
  }
});

